36: function drawTrend(){const c=$('#trend-canvas');if(!c)return;let r=c.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);c.width=r.width*dpr;c.height=r.height*dpr;let ctx=c.getContext('2d');ctx.scale(dpr,dpr);let w=r.width,h=r.height,history=S.history.slice(-24),vals=history.length?history.map(x=>x.fitness):Array.from({length:18},(_,i)=>S.fitness-Math.sin(i*.65)*.05+i*.001);let min=Math.min(...vals)-.04,max=Math.max(...vals)+.05;ctx.strokeStyle='#22322b';ctx.lineWidth=1;for(let i=1;i<4;i++){let y=h*i/4;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}let pts=vals.map((v,i)=>({x:i/(vals.length-1||1)*w,y:h-((v-min)/(max-min||1))*(h-18)-8}));let grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,'#c6f36b33');grad.addColorStop(1,'#c6f36b00');ctx.beginPath();ctx.moveTo(pts[0].x,h);pts.forEach(p=>ctx.lineTo(p.x,p.y));ctx.lineTo(w,h);ctx.closePath();ctx.fillStyle=grad;ctx.fill();ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.strokeStyle='#c6f36b';ctx.lineWidth=1.7;ctx.stroke();pts.forEach((p,i)=>{if(i===pts.length-1){ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fillStyle='#d9f99c';ctx.fill()}})}
