function handleAction(action){let a=typeof action==='string'?action:action.dataset.action;switch(a){case'toggle':S.playing=!S.playing;storeState();render();toast(S.playing?'Simulation resumed.':'Simulation paused.');break;case'sample':sample();break;case'sequence':doSequence();break;case'save-genome':saveGenome();break;case'run-lab':runLab();break;case'evolve':S.playing=false;for(let i=0;i<10;i++){S.tick+=25;generationStep()}storeState();render();toast('Ten generations simulated with inherited variation.');break;case'plate-live':{let added=addCellsToPlate(S.genome,false,6);render();if(added.length)toast(`${added.length} live cells added to the observatory plate.`);break}case'plate-archive':{let value=$('#plate-archive')?.value,index=Number(value),genome=value!==''?S.archive?.[index]:null;if(!Number.isInteger(index)||!genome){toast('Choose an archived genome first.');return}let added=addCellsToPlate(genome,true,6);render();if(added.length)toast(`${added.length} cells from ${genome.id} added to the plate.`);break}case'inspect-genome':{let cell=S.plate.find(c=>c.id===S.selectedCellId);if(!cell)return;S.inspectedGenome=JSON.parse(JSON.stringify(plateGenome(cell)));S.selectedGene=0;currentView='genome';render();break}case'clear-inspection':delete S.inspectedGenome;S.selectedGene=0;render();break;case'cell-cycle':S.atp=clamp(S.atp-.12,.2,7);S.cellCount=Math.round(S.cellCount*(1+S.fitness*.008));S.events.unshift({tick:S.tick,type:'lab',text:'Representative cell completed a modeled cycle; ATP proxy decreased.'});addNotebook('Cell cycle observation',`A modeled cell cycle advanced. ATP proxy ${f(S.atp,2)} mmol/L; cell count ${S.cellCount.toLocaleString()}.`,'CELL CYCLE');storeState();render();toast('Cell cycle advanced.');break;case'stain':S.events.unshift({tick:S.tick,type:'lab',text:'Fluorescent viability stain applied to representative cell sample.'});addNotebook('Fluorescent stain applied','Virtual viability stain applied; fluorescence intensity maps to current viability proxy.','STAINING');storeState();render();toast('Fluorescence reveals viable-cell signal.');break;case'add-note':$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><h2>Add field note</h2><button class="modal-close" data-action="close-modal">×</button></div><label>Observation title</label><input id="note-title" placeholder="e.g. Increased stress response" maxlength="90"><label>Notes / hypothesis</label><textarea id="note-body" placeholder="Record an observation, hypothesis, or next step…"></textarea><div class="modal-footer"><button class="subtle-button" data-action="close-modal">Cancel</button><button class="action-button primary" data-action="save-note">Save to notebook</button></div></div></div>`;break;case'save-note':{let title=$('#note-title')?.value.trim(),text=$('#note-body')?.value.trim();if(!title||!text){toast('Add a title and observation first.');return}addNotebook(title,text);$('#modal-root').innerHTML='';currentView='notebook';render();toast('Field note saved.');break}case'export':download('genesis-database.json',JSON.stringify({format:'genesis-genome-archive-v1',archive:S.archive||[],notebook:S.notebook||[]},null,2));break;case'import':$('#import-file').click();break;case'download-genome':{let g=S.archive[Number(action.dataset.index)];if(g)download(`${g.id}.json`,JSON.stringify(g,null,2));break}case'use-genome':{let g=S.archive[Number(action.dataset.index)];if(g)newWorld(g);break}case'close-modal':$('#modal-root').innerHTML='';break;case'reset-world':$('#modal-root').innerHTML='';newWorld();break}}
document.addEventListener('click',e=>{let nav=e.target.closest('[data-view]');if(nav){currentView=nav.dataset.view;render();return}let plateCell=e.target.closest('[data-plate-cell]');if(plateCell){S.selectedCellId=plateCell.dataset.plateCell;storeState();render();return}let action=e.target.closest('[data-action]');if(action){handleAction(action);return}let p=e.target.closest('[data-protocol]');if(p){activeProtocol=p.dataset.protocol;render();return}let sp=e.target.closest('[data-speed]');if(sp){S.speed=Number(sp.dataset.speed);storeState();render();return}let gene=e.target.closest('[data-gene]');if(gene){S.selectedGene=Number(gene.dataset.gene);render();return}if(e.target.closest('#new-world')){newWorld();return}if(e.target.closest('#settings-btn')){$('#modal-root').innerHTML=settingsModal();return}if(e.target.closest('#seed-button')){navigator.clipboard?.writeText(String(S.seed));toast('World seed copied.');return}if(e.target.classList.contains('modal-backdrop'))$('#modal-root').innerHTML=''});
