div></section></div><section class="card" style="margin-top:14px"><div class="card-head"><span class="card-title">Environmental conditions</span><span class="card-meta">CHANGES AFFECT REGULATORY EXPRESSION & FITNESS</span></div><div class="env-grid">${[['temperature','Temperature','°C',0,40],['radiation','Radiation','relative',0,1],['nutrients','Nutrient availability','fraction',0,1],['oxygen','Oxygen availability','fraction',0,1],['water','Water availability','fraction',0,1],['ph','pH','',4,10],['chemical','Chemical stress','relative',0,1]].map(([key,label,unit,min,max])=>`<div class="env-control"><label><span>${label}</span><b>${f(S.env[key],1)} ${unit}</b></label><input type="range" min="${min}" max="${max}" step=".1" value="${S.env[key]}" data-env="${key}" /></div>`).join('')}</div></section>`}
